declare(strict_types=1);
// Copia congelada (commit 70142fe) de la sentencia de Auth::deviceContext anterior a 2026-10-19: devices JOIN tenants JOIN users
// ... FOR UPDATE, que tomaba en exclusivo la fila del cliente en cada envio. Solo para comparar en tests/auth-locks.php.
// Argumentos: [key_id, tenant_id, device_id].
const AUTH_LEGACY_CONTEXT_SQL = 'SELECT d.tenant_id,d.id device_id,d.user_id,d.auth_version device_auth_version,d.agent_version,d.release_ring,d.specs,t.auth_version tenant_auth_version,t.timezone,u.auth_version user_auth_version,a.id assignment_id,a.starts_at assignment_start,a.ends_at assignment_end,k.id key_id,k.jwk_x,k.jwk_y,k.thumbprint,p.id principal_id,e.id enrollment_id FROM devices d JOIN tenants t ON t.tenant_id=d.tenant_id JOIN users u ON u.tenant_id=d.tenant_id AND u.id=d.user_id JOIN device_assignments a ON a.tenant_id=d.tenant_id AND a.device_id=d.id AND a.user_id=d.user_id AND a.starts_at<=UTC_TIMESTAMP(6) AND (a.ends_at IS NULL OR a.ends_at>UTC_TIMESTAMP(6)) JOIN device_keys k ON k.tenant_id=d.tenant_id AND k.device_id=d.id AND k.id=? AND k.revoked_at IS NULL JOIN principals p ON p.tenant_id=d.tenant_id AND p.device_id=d.id AND p.kind=\'device\' JOIN enrollments e ON e.tenant_id=d.tenant_id AND e.device_id=d.id AND e.public_key_thumbprint=k.thumbprint AND e.status=\'consumed\' WHERE d.tenant_id=? AND d.id=? AND d.status=\'active\' AND t.status=\'active\' AND u.status=\'active\' FOR UPDATE';
